<script setup lang="ts">
import { ref } from 'vue'
import { Building2, ChevronRight, Pencil, Plus, Target, Users } from 'lucide-vue-next'
import { useResource } from '../api'
import type { Employee, Goal, Role, Team } from '../types'
import PageTitle from '../components/PageTitle.vue'
import ResourceState from '../components/ResourceState.vue'
import StatusTag from '../components/StatusTag.vue'
import EntityForm from '../components/EntityForm.vue'
import AccessManagement from '../components/AccessManagement.vue'
const teams = useResource<Team[]>('/teams', []), roles = useResource<Role[]>('/roles', []), employees = useResource<Employee[]>('/employees', []), goals = useResource<Goal[]>('/goals', [])
const form = ref(''), editRecord = ref<Record<string, unknown>>()
function open(kind: string, record?: unknown) { editRecord.value = record as Record<string, unknown> | undefined; form.value = kind }
function owner(id: string | null) { return employees.data.value.find(employee => employee.id === id)?.name || '团队共同目标' }
</script>
<template>
  <PageTitle title="数字团队与岗位" subtitle="按岗位建立员工，按业务目标分配责任。员工拥有独立身份，不固定绑定服务器。" eyebrow="PEOPLE / ROLES & OUTCOMES"><el-dropdown @command="(kind: string) => open(kind)"><el-button :icon="Plus">团队 / 岗位 / 目标</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="team">建立团队</el-dropdown-item><el-dropdown-item command="role">建立岗位</el-dropdown-item><el-dropdown-item command="goal">设定目标</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button type="primary" :icon="Plus" @click="open('employee')">创建数字员工</el-button></PageTitle>
  <div class="section-title"><h2><Building2 :size="17"/>团队</h2><span class="caption">人类与员工的组织范围</span></div><ResourceState :loading="teams.loading.value" :error="teams.error.value" :empty="!teams.data.value.length" description="先建立团队，再配置岗位与数字员工" @retry="teams.load"><div class="team-strip"><article v-for="team in teams.data.value" :key="team.id" class="panel team-card"><span class="avatar"><Building2 :size="21"/></span><div><h3>{{ team.name }}</h3><p>{{ employees.data.value.filter(item => item.team_id === team.id).length }} 位数字员工 · {{ roles.data.value.filter(item => item.team_id === team.id).length }} 个岗位</p></div></article></div></ResourceState>
  <div class="section-title"><h2><Users :size="17"/>共享岗位，独立责任</h2><el-button text :icon="Plus" @click="open('role')">建立岗位</el-button></div><ResourceState :loading="roles.loading.value" :error="roles.error.value" :empty="!roles.data.value.length" description="尚未建立业务岗位" @retry="roles.load"><div class="card-grid"><article v-for="role in roles.data.value" :key="role.id" class="panel role-card"><div class="spread"><span class="avatar"><Users :size="21"/></span><el-button text circle :icon="Pencil" :aria-label="`编辑岗位 ${role.name}`" @click="open('role', role)"/></div><h2>{{ role.name }}</h2><p>{{ role.mandate || '尚未配置长期职责' }}</p><div class="tag-wrap"><el-tag v-for="permission in role.permissions.slice(0,3)" :key="permission" type="info">{{ permission }}</el-tag><el-tag v-if="role.permissions.length > 3" type="info">+{{ role.permissions.length - 3 }}</el-tag></div><div class="spread role-footer"><span class="caption">{{ teams.data.value.find(item => item.id === role.team_id)?.name }} · 版本 {{ role.revision }}</span><el-tag round>{{ employees.data.value.filter(item => item.role_id === role.id).length }} 位员工</el-tag></div></article></div></ResourceState>
  <div class="section-title"><h2><Target :size="17"/>团队目标与责任</h2><el-button text :icon="Plus" @click="open('goal')">设定目标</el-button></div><ResourceState :loading="goals.loading.value" :error="goals.error.value" :empty="!goals.data.value.length" description="尚未设定持续工作目标" @retry="goals.load"><div class="two-column"><article v-for="goal in goals.data.value" :key="goal.id" class="panel goal-card"><div class="spread"><h3>{{ goal.title }}</h3><StatusTag :value="goal.status"/></div><p>{{ goal.metric }}</p><div class="spread"><span class="caption">主责 {{ owner(goal.owner_employee_id) }} · 版本 {{ goal.revision }}</span><el-button text :icon="Pencil" @click="open('goal', goal)">调整目标</el-button></div></article></div></ResourceState>
  <div class="section-title"><h2>管理员工</h2><span class="caption">归档前必须处理未完成责任，私人对话不会随岗位交接复制</span></div><section class="panel"><ResourceState :loading="employees.loading.value" :error="employees.error.value" :empty="!employees.data.value.length" description="尚未创建数字员工" @retry="employees.load"><el-table :data="employees.data.value"><el-table-column label="员工" min-width="150"><template #default="{ row }"><div class="person-cell"><span class="avatar avatar-small">{{ row.name.slice(0,1) }}</span><strong>{{ row.name }}</strong></div></template></el-table-column><el-table-column label="业务岗位" min-width="160"><template #default="{ row }">{{ roles.data.value.find(item => item.id === row.role_id)?.name }}</template></el-table-column><el-table-column label="所属团队" min-width="130"><template #default="{ row }">{{ teams.data.value.find(item => item.id === row.team_id)?.name }}</template></el-table-column><el-table-column label="管理状态" min-width="120"><template #default="{ row }"><StatusTag :value="row.lifecycle"/></template></el-table-column><el-table-column label="每日 Token 预算" min-width="140"><template #default="{ row }">{{ row.daily_token_budget.toLocaleString() }}</template></el-table-column><el-table-column label="操作" min-width="180"><template #default="{ row }"><el-button text :icon="Pencil" @click="open('employee', row)">授权与职责</el-button><RouterLink :to="`/employees/${row.id}`"><el-button text type="primary">对话 <ChevronRight :size="13"/></el-button></RouterLink></template></el-table-column></el-table></ResourceState></section>
  <EntityForm :model-value="!!form" :kind="form" :record="editRecord" @update:model-value="form = ''"/>
  <AccessManagement/>
</template>
